// CashALL Unified Catalog Store
// Mobiles, Laptops, and Tablets (+5% Increased Final Prices)

import { SERVICEABLE_DISTRICTS } from "./serviceability";

export interface BrandData {
  id: string;
  name: string;
  slug: string;
  logoUrl?: string | null;
  category: "MOBILE" | "LAPTOP" | "TABLET" | "BOTH" | "ALL" | "MOBILE_TABLET" | "LAPTOP_TABLET" | string;
  sortOrder: number;
  active: boolean;
}

export interface DeviceModelData {
  id: string;
  brandId: string;
  brandSlug?: string;
  name: string;
  slug: string;
  imageUrl?: string | null;
  releaseYear?: number;
  popular: boolean;
  active: boolean;
  contactForPrice?: boolean;
  category?: "MOBILE" | "LAPTOP" | "TABLET" | string;
}

export interface DeviceVariantData {
  id: string;
  modelId: string;
  ram?: string;
  storage: string;
  basePrice: number;
  active: boolean;
}

export interface QuestionOptionData {
  id: string;
  label: string;
  description?: string;
  iconName?: string;
  sortOrder: number;
}

export interface QuestionData {
  id: string;
  title: string;
  subtitle?: string;
  group: "BASIC" | "SCREEN" | "BODY" | "FUNCTIONAL" | "REPAIR" | "ACCESSORIES";
  type: "SINGLE" | "MULTIPLE";
  sortOrder: number;
  options: QuestionOptionData[];
}

export interface PricingRuleData {
  id: string;
  questionId: string;
  optionId: string;
  adjustmentType: "FIXED_DEDUCTION" | "PERCENTAGE_DEDUCTION" | "FIXED_BONUS" | "PERCENTAGE_BONUS";
  adjustmentValue: number;
}

export interface QuoteData {
  id: string;
  quoteNumber: string;
  variantId: string;
  selectedAnswersJson: string;
  basePrice: number;
  totalDeductions: number;
  estimatedPrice: number;
  breakdownJson: string;
  expiresAt: string;
  status: "ACTIVE" | "ORDERED" | "EXPIRED" | "CANCELLED";
  createdAt: string;
}

export interface OrderData {
  id: string;
  orderNumber: string;
  quoteId: string;
  userId: string;
  customerName: string;
  customerPhone: string;
  customerEmail?: string;
  deviceName?: string;
  addressId?: string;
  addressSummary?: string;
  pincode: string;
  pickupDate: string;
  pickupTimeSlot: string;
  status: string;
  assignedPartnerId?: string;
  assignedPartnerName?: string;
  assignedPartnerPhone?: string;
  assignedPartnerBusiness?: string;
  estimatedPrice?: number;
  revisedPrice?: number;
  priceDifferenceReason?: string;
  declaredConditionSummary?: string;
  inspectedConditionSummary?: string;
  imeiNumber?: string;
  paymentStatus?: "PENDING" | "PROCESSING" | "PAID" | "FAILED";
  paymentTxRef?: string;
  createdAt: string;
  updatedAt: string;
}

export interface ServiceAreaData {
  id: string;
  pincode: string;
  city: string;
  state: string;
  active: boolean;
  pickupAvailable: boolean;
}

export interface PartnerData {
  id: string;
  name: string;
  phone: string;
  email: string;
  businessName: string;
  city: string;
  status: "ACTIVE" | "PENDING" | "SUSPENDED";
  rating: number;
  completedPickups: number;
}

export interface FAQData {
  id: string;
  question: string;
  answer: string;
  category: string;
}

